-- Add requirements_manual flag to distinguish admin-written requirements from adapter-generated ones
-- This ensures adapter-generated requirements don't block step extraction from raw_payload

ALTER TABLE public.offers 
ADD COLUMN IF NOT EXISTS requirements_manual boolean NOT NULL DEFAULT false;

COMMENT ON COLUMN public.offers.requirements_manual IS 
  'True when requirements text was manually set by admin. False when auto-generated by adapter. When false, steps are extracted from raw_payload if available.';

-- Index for performance
CREATE INDEX IF NOT EXISTS idx_offers_requirements_manual 
  ON public.offers(requirements_manual) 
  WHERE requirements_manual = true;
